31	import org.springframework.http.ResponseEntity;
32	import org.springframework.samples.petclinic.mapper.OwnerMapper;
33	import org.springframework.samples.petclinic.mapper.PetMapper;
34	import org.springframework.samples.petclinic.mapper.VisitMapper;
35	import org.springframework.samples.petclinic.model.Owner;
36	import org.springframework.samples.petclinic.model.Pet;
37	import org.springframework.samples.petclinic.model.Visit;
38	import org.springframework.samples.petclinic.rest.api.OwnersApi;
39	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
40	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
41	import org.springframework.samples.petclinic.rest.dto.PetDto;
42	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
43	import org.springframework.samples.petclinic.rest.dto.VisitDto;
44	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
45	import org.springframework.samples.petclinic.service.ClinicService;
46	import org.springframework.samples.petclinic.rest.advice.DailyOwnerRegistrationLimitException;
47	import org.springframework.samples.petclinic.rest.advice.DuplicateOwnerIdentityException;
48	import org.springframework.samples.petclinic.rest.advice.InvalidOwnerFieldsException;
49	import org.springframework.samples.petclinic.rest.advice.OwnerCityAtCapacityException;
50	import org.springframework.samples.petclinic.rest.validation.AddressNormalizer;
51	import org.springframework.samples.petclinic.rest.validation.EmailNormalizer;
52	import org.springframework.samples.petclinic.rest.validation.TelephoneNormalizer;
53	import org.springframework.security.access.prepost.PreAuthorize;
54	import org.springframework.web.bind.annotation.CrossOrigin;
55	import org.springframework.web.bind.annotation.RequestMapping;
56	import org.springframework.web.bind.annotation.RestController;
57	import org.springframework.web.util.UriComponentsBuilder;
58	
59	import jakarta.transaction.Transactional;
60	
61	/**
62	 * @author Vitaliy Fedoriv
63	 */
64	
65	@RestController
66	@CrossOrigin(exposedHeaders = "errors, content-type")
67	@RequestMapping("/api")
68	public class OwnerRestControllerV1 implements OwnersApi {
69	
70	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
71	
72	    private final ClinicService clinicService;
73	
74	    private final OwnerMapper ownerMapper;
75	
76	    private final PetMapper petMapper;
77	
78	    private final VisitMapper visitMapper;
79	
80	    private final TelephoneNormalizer telephoneNormalizer;
81	
82	    private final AddressNormalizer addressNormalizer;
83	
84	    private final EmailNormalizer emailNormalizer;
85	
86	    public OwnerRestControllerV1(ClinicService clinicService,
87	                                 OwnerMapper ownerMapper,
88	                                 PetMapper petMapper,
89	                                 VisitMapper visitMapper,
90	                                 TelephoneNormalizer telephoneNormalizer,
91	                                 AddressNormalizer addressNormalizer,
92	                                 EmailNormalizer emailNormalizer) {
93	        this.clinicService = clinicService;
94	        this.ownerMapper = ownerMapper;
95	        this.petMapper = petMapper;
96	        this.visitMapper = visitMapper;
97	        this.telephoneNormalizer = telephoneNormalizer;
98	        this.addressNormalizer = addressNormalizer;
99	        this.emailNormalizer = emailNormalizer;
100	    }
101	
102	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
103	    @Override
104	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
105	        Collection<Owner> owners;
106	        if (lastName != null) {
107	            owners = this.clinicService.findOwnerByLastName(lastName);
108	        } else {
109	            owners = this.clinicService.findAllOwners();
110	        }
111	        if (owners.isEmpty()) {
112	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
113	        }
114	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
115	    }
116	
117	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
118	    @Override
119	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
120	        return withOwner(ownerId, owner ->
121	            new ResponseEntity<>(toOwnerDtoWithDerivedFields(owner), HttpStatus.OK));
122	    }
123	
124	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
125	    @Override
126	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
127	        ownerFieldsDto.setAddress(addressNormalizer.normalize(ownerFieldsDto.getAddress()));
128	        rejectBlankOwnerFields(ownerFieldsDto);
129	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
130	        rejectCityAtCapacity(ownerFieldsDto.getCity());
131	        LocalDate registrationDate = businessDay(effectiveRegistrationDate(ownerFieldsDto.getRegistrationDate()));
132	        rejectDailyRegistrationLimit(registrationDate);
133	        String normalizedTelephone = telephoneNormalizer.normalize(ownerFieldsDto.getTelephone());
134	        ownerFieldsDto.setTelephone(normalizedTelephone);
135	        String normalizedEmail = emailNormalizer.normalize(ownerFieldsDto.getEmail());
136	        ownerFieldsDto.setEmail(normalizedEmail);
137	        HttpHeaders headers = new HttpHeaders();
138	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
139	        owner.setRegistrationDate(registrationDate);
140	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
141	        owner.setNamesakeCount(namesakeCount(owner.getFirstName(), owner.getLastName()));
142	        if (sharesHousehold) {
143	            owner.setHouseholdId(householdId(owner.getLastName(), owner.getAddress()));
144	        }
145	        rejectDuplicateIdentity(owner);
146	        this.clinicService.saveOwner(owner);
147	        AUDIT.info("Owner created: id={} customerCode={} registrationDate={} membershipLevel={}",
148	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
149	            ownerMapper.membershipLevel(owner));
150	        OwnerDto ownerDto = toOwnerDtoWithDerivedFields(owner);
151	        headers.setLocation(UriComponentsBuilder.newInstance()
152	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
153	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
154	    }
155	
156	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
157	    @Override
158	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
159	        return withOwner(ownerId, currentOwner -> {
160	            currentOwner.setAddress(ownerFieldsDto.getAddress());
161	            currentOwner.setCity(ownerFieldsDto.getCity());
162	            currentOwner.setFirstName(ownerFieldsDto.getFirstName());
163	            currentOwner.setLastName(ownerFieldsDto.getLastName());
164	            currentOwner.setTelephone(ownerFieldsDto.getTelephone());
165	            currentOwner.setEmail(emailNormalizer.normalize(ownerFieldsDto.getEmail()));
166	            this.clinicService.saveOwner(currentOwner);
167	            return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
168	        });
169	    }
170	
171	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
172	    @Transactional
173	    @Override
174	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
175	        return withOwner(ownerId, owner -> {
176	            this.clinicService.deleteOwner(owner);
177	            return new ResponseEntity<>(HttpStatus.NO_CONTENT);
178	        });
179	    }
180	
181	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
182	    @Override
183	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
184	        return withOwner(ownerId, owner -> {
185	            HttpHeaders headers = new HttpHeaders();
186	            Pet pet = petMapper.toPet(petFieldsDto);
187	            owner.setId(ownerId);
188	            pet.setOwner(owner);
189	            pet.getType().setName(null);
190	            this.clinicService.savePet(pet);
191	            PetDto petDto = petMapper.toPetDto(pet);
192	            headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
193	                .buildAndExpand(pet.getId()).toUri());
194	            return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
195	        });
196	    }
197	
198	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
199	    @Override
200	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
201	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
202	        if (currentOwner != null) {
203	            Pet currentPet = this.clinicService.findPetById(petId);
204	            if (currentPet != null) {
205	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
206	                currentPet.setName(petFieldsDto.getName());
207	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
208	                this.clinicService.savePet(currentPet);
209	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
210	            }
211	        }
212	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
213	    }
214	
215	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
216	    @Override
217	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
218	        HttpHeaders headers = new HttpHeaders();
219	        Visit visit = visitMapper.toVisit(visitFieldsDto);
220	        Pet pet = new Pet();
221	        pet.setId(petId);
222	        visit.setPet(pet);
223	        this.clinicService.saveVisit(visit);
224	        VisitDto visitDto = visitMapper.toVisitDto(visit);
225	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
226	            .buildAndExpand(visit.getId()).toUri());
227	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
228	    }
229	
230	
231	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
232	    @Override
233	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
234	        Owner owner = this.clinicService.findOwnerById(ownerId);
235	        if (owner != null) {
236	            Pet pet = owner.getPet(petId);
237	            if (pet != null) {
238	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
239	            }
240	        }
241	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
242	    }
243	
244	    /**
245	     * Loads the owner with the given id and, when it exists, produces the response through
246	     * {@code action}; when no such owner exists a {@code 404 Not Found} is returned instead. The
247	     * single-owner endpoints share this "find the owner or report 404" preamble, so the lookup and
248	     * the not-found response are written in exactly one place rather than copied into each method.
249	     *
250	     * @param ownerId the id of the owner to load
251	     * @param action builds the response for an existing owner
252	     * @param <T> the response body type
253	     * @return the result of {@code action} for an existing owner, otherwise a 404 response
254	     */
255	    private <T> ResponseEntity<T> withOwner(Integer ownerId, Function<Owner, ResponseEntity<T>> action) {
256	        Owner owner = this.clinicService.findOwnerById(ownerId);
257	        if (owner == null) {
258	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
259	        }
260	        return action.apply(owner);
261	    }
262	
263	    /**
264	     * Maps a persisted owner to its {@link OwnerDto} and populates the read-only fields that are
265	     * derived from server-side state rather than stored columns (the {@code bulkSignupWarning} flag
266	     * and the {@code identityKey}). Both the create endpoint and the single-owner read endpoint
267	     * return their owner through this method, so an owner is decorated identically on either path
268	     * and each derived field is computed in exactly one place.
269	     *
270	     * @param owner the persisted owner to represent
271	     * @return the owner DTO with its derived read-only fields populated
272	     */
273	    private OwnerDto toOwnerDtoWithDerivedFields(Owner owner) {
274	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
275	        ownerDto.setBulkSignupWarning(bulkSignupWarning(owner.getRegistrationDate()));
276	        ownerDto.setIdentityKey(identityKey(owner));
277	        return ownerDto;
278	    }
279	
280	    /**
281	     * Rejects an owner whose required text fields are blank (whitespace-only). Missing (null)
282	     * and empty fields are already rejected by Bean Validation on {@link OwnerFieldsDto}; this
283	     * closes the gap for {@code address} and {@code city}, whose values may be non-empty yet
284	     * blank (e.g. {@code "   "}). The offending field names are reported through an
285	     * {@link InvalidOwnerFieldsException}, which the {@code ExceptionControllerAdvice} renders
286	     * as a 400 response carrying an {@code errors} array of field names.
287	     *
288	     * @param ownerFieldsDto the submitted owner fields
289	     * @throws InvalidOwnerFieldsException if one or more required fields are blank
290	     */
291	    private void rejectBlankOwnerFields(OwnerFieldsDto ownerFieldsDto) {
292	        List<String> blankFields = new ArrayList<>();
293	        addIfBlank(blankFields, "firstName", ownerFieldsDto.getFirstName());
294	        addIfBlank(blankFields, "lastName", ownerFieldsDto.getLastName());
295	        addIfBlank(blankFields, "address", ownerFieldsDto.getAddress());
296	        addIfBlank(blankFields, "city", ownerFieldsDto.getCity());
297	        addIfBlank(blankFields, "telephone", ownerFieldsDto.getTelephone());
298	        if (!blankFields.isEmpty()) {
299	            throw new InvalidOwnerFieldsException(blankFields);
300	        }
301	    }
302	
303	    private void addIfBlank(List<String> blankFields, String field, String value) {
304	        if (value != null && value.isBlank()) {
305	            blankFields.add(field);
306	        }
307	    }
308	
309	    /**
310	     * Builds the {@code customerCode} assigned to a newly created owner, formatted
311	     * {@code '<CITY3>-<LAST3>-<NNNN>'}: {@code CITY3} is the upper-cased first three letters of the
312	     * owner's {@code city}, {@code LAST3} is the upper-cased first three letters of the owner's
313	     * {@code lastName}, and {@code NNNN} is a per-city 4-digit zero-padded sequence equal to one
314	     * more than the number of owners already in that city (e.g. {@code 'MEL-SMI-0007'}).
315	     *
316	     * @param city the city of the owner being created
317	     * @param lastName the last name of the owner being created
318	     * @return the formatted customer code
319	     */
320	    private String nextCustomerCode(String city, String lastName) {
321	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase(java.util.Locale.ROOT);
322	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(java.util.Locale.ROOT);
323	        long sequence = ownersInCity(city) + 1L;
324	        return String.format("%s-%s-%04d", city3, last3, sequence);
325	    }
326	
327	    /**
328	     * Counts how many existing owners already share the given {@code firstName} and {@code lastName},
329	     * compared case-insensitively (using {@link java.util.Locale#ROOT}-independent
330	     * {@link String#equalsIgnoreCase(String)}). The count reflects the owners present before the
331	     * current create, so a name that is unique on create yields {@code 0}. The value is stored on the
332	     * new owner and surfaced as the read-only {@code namesakeCount} field.
333	     *
334	     * @param firstName the first name of the owner being created
335	     * @param lastName the last name of the owner being created
336	     * @return the number of existing owners with the same first and last name (case-insensitive)
337	     */
338	    private int namesakeCount(String firstName, String lastName) {
339	        return (int) this.clinicService.findAllOwners().stream()
340	            .filter(owner -> equalsIgnoreCase(owner.getFirstName(), firstName)
341	                && equalsIgnoreCase(owner.getLastName(), lastName))
342	            .count();
343	    }
344	
345	    private boolean equalsIgnoreCase(String a, String b) {
346	        return a == null ? b == null : a.equalsIgnoreCase(b);
347	    }
348	
349	    /**
350	     * The maximum number of owners a single city may contain. Once a city already holds this many
351	     * owners, further owners in that city are rejected by {@link #rejectCityAtCapacity(String)}.
352	     */
353	    private static final long MAX_OWNERS_PER_CITY = 50L;
354	
355	    /**
356	     * Rejects a create request whose city already contains {@link #MAX_OWNERS_PER_CITY} or more
357	     * owners. Existing owners are matched to the requested city case-insensitively (using
358	     * {@link java.util.Locale#ROOT}-independent {@link String#equalsIgnoreCase(String)}), mirroring
359	     * the per-city counting used for the customer code. A city at capacity is reported through an
360	     * {@link OwnerCityAtCapacityException}, which the {@code ExceptionControllerAdvice} renders as a
361	     * 409 Conflict response.
362	     *
363	     * @param city the city of the owner being created
364	     * @throws OwnerCityAtCapacityException if the city already holds the maximum number of owners
365	     */
366	    private void rejectCityAtCapacity(String city) {
367	        if (ownersInCity(city) >= MAX_OWNERS_PER_CITY) {
368	            throw new OwnerCityAtCapacityException(city);
369	        }
370	    }
371	
372	    /**
373	     * Counts the existing owners whose {@code city} matches the given city, compared
374	     * case-insensitively (see {@link #equalsIgnoreCase(String, String)}). Shared by the per-city
375	     * customer-code sequence ({@link #nextCustomerCode(String, String)}) and the per-city capacity
376	     * check ({@link #rejectCityAtCapacity(String)}) so both count a city's owners identically.
377	     *
378	     * @param city the city to count owners for
379	     * @return the number of existing owners in that city
380	     */
381	    private long ownersInCity(String city) {
382	        return this.clinicService.findAllOwners().stream()
383	            .filter(owner -> equalsIgnoreCase(owner.getCity(), city))
384	            .count();
385	    }
386	
387	    /**
388	     * The maximum number of owners that may be registered on a single day. Once this many owners
389	     * already carry a given {@code registrationDate}, further owners for that date are rejected by
390	     * {@link #rejectDailyRegistrationLimit(LocalDate)}.
391	     */
392	    private static final long MAX_OWNERS_PER_DAY = 100L;
393	
394	    /**
395	     * Resolves the effective registration date for a create request: the value supplied in the
396	     * request when present, otherwise the server's current date. The result is the raw effective
397	     * date before the business-day adjustment applied by {@link #businessDay(LocalDate)}.
398	     *
399	     * @param suppliedDate the registration date from the request, or {@code null} when omitted
400	     * @return the supplied date, or today when none was supplied
401	     */
402	    private LocalDate effectiveRegistrationDate(LocalDate suppliedDate) {
403	        return suppliedDate != null ? suppliedDate : LocalDate.now();
404	    }
405	
406	    /**
407	     * Adjusts a date so it falls on a business day. A Saturday is rolled forward to the following
408	     * Monday and a Sunday to the next day (Monday); any weekday is returned unchanged. Applied to
409	     * the effective registration date so that a weekend value - whether supplied in the request or
410	     * defaulted to the server date - is stored as the next Monday, and every value derived from the
411	     * registration date (such as the membership number's year segment and the daily create-limit
412	     * bucket) uses the adjusted business day.
413	     *
414	     * @param date the effective registration date
415	     * @return the same date when it is a weekday, otherwise the next Monday
416	     */
417	    private LocalDate businessDay(LocalDate date) {
418	        DayOfWeek dayOfWeek = date.getDayOfWeek();
419	        if (dayOfWeek == DayOfWeek.SATURDAY) {
420	            return date.plusDays(2);
421	        }
422	        if (dayOfWeek == DayOfWeek.SUNDAY) {
423	            return date.plusDays(1);
424	        }
425	        return date;
426	    }
427	
428	    /**
429	     * Rejects a create request once {@link #MAX_OWNERS_PER_DAY} or more owners have already been
430	     * created on the given day, counted by {@code registrationDate}. A day at capacity is reported
431	     * through a {@link DailyOwnerRegistrationLimitException}, which the {@code ExceptionControllerAdvice}
432	     * renders as a 429 Too Many Requests response.
433	     *
434	     * @param date the registration date of the owner being created (today)
435	     * @throws DailyOwnerRegistrationLimitException if the day already holds the maximum number of owners
436	     */
437	    private void rejectDailyRegistrationLimit(LocalDate date) {
438	        if (ownersRegisteredOn(date) >= MAX_OWNERS_PER_DAY) {
439	            throw new DailyOwnerRegistrationLimitException(date);
440	        }
441	    }
442	
443	    /**
444	     * Counts the existing owners whose {@code registrationDate} equals the given day. Shared by the
445	     * hard daily create limit ({@link #rejectDailyRegistrationLimit(LocalDate)}) and the soft
446	     * {@code bulkSignupWarning} flag ({@link #bulkSignupWarning(LocalDate)}) so both accumulate a
447	     * day's owners identically.
448	     *
449	     * @param date the registration date to count owners for
450	     * @return the number of existing owners registered on that day
451	     */
452	    private long ownersRegisteredOn(LocalDate date) {
453	        return this.clinicService.findAllOwners().stream()
454	            .filter(owner -> date.equals(owner.getRegistrationDate()))
455	            .count();
456	    }
457	
458	    /**
459	     * The soft daily create threshold above which the read-only {@code bulkSignupWarning} flag is
460	     * raised. Once more than this many owners share a {@code registrationDate}, that day is flagged
461	     * as unusually high volume - a warning well below the hard {@link #MAX_OWNERS_PER_DAY} cap.
462	     */
463	    private static final long BULK_SIGNUP_WARNING_THRESHOLD = 80L;
464	
465	    /**
466	     * Derives the read-only {@code bulkSignupWarning} flag for an owner: {@code true} when more than
467	     * {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners have been created (counted by
468	     * {@code registrationDate}) on the given day, otherwise {@code false}. Uses the same per-day
469	     * accumulation as {@link #rejectDailyRegistrationLimit(LocalDate)}. A {@code null} date (an owner
470	     * without a registration date, such as seed data) is never flagged.
471	     *
472	     * @param date the owner's registration date (the day it was created), or {@code null}
473	     * @return {@code true} if the day already holds more than the warning threshold of owners
474	     */
475	    private boolean bulkSignupWarning(LocalDate date) {
476	        if (date == null) {
477	            return false;
478	        }
479	        return ownersRegisteredOn(date) > BULK_SIGNUP_WARNING_THRESHOLD;
480	    }
481	
482	    /**
483	     * Rejects a create request whose derived {@code identityKey} exactly equals an existing owner's.
484	     * The identity key consolidates the former separate telephone, email and household duplicate
485	     * checks into a single value: {@code normalizedTelephone + '|' + (email or empty) + '|' +
486	     * (householdId or empty)} (see {@link #identityKey(Owner)}). Because the telephone is part of the
487	     * key, two members of the same household (same {@code householdId}) with different telephones have
488	     * different identity keys and are both allowed; only an exact full-key match is a duplicate. A
489	     * collision is reported through a {@link DuplicateOwnerIdentityException}, which the
490	     * {@code ExceptionControllerAdvice} renders as a 409 Conflict response.
491	     *
492	     * @param owner the fully-populated owner being created (telephone, email and household id set)
493	     * @throws DuplicateOwnerIdentityException if an existing owner has the same identity key
494	     */
495	    private void rejectDuplicateIdentity(Owner owner) {
496	        String key = identityKey(owner);
497	        boolean duplicate = existingOwnerMatches(this::identityKey, key);
498	        if (duplicate) {
499	            throw new DuplicateOwnerIdentityException(key);
500	        }
501	    }
502	
503	    /**
504	     * Reduces an owner to its derived {@code identityKey}, formatted
505	     * {@code '<normalizedTelephone>|<email>|<householdId>'}: the owner's telephone reduced to its
506	     * canonical E.164 form (see {@link TelephoneNormalizer#canonicalize(String)}), the owner's
507	     * normalized (lower-cased) email or the empty string when absent (see
508	     * {@link EmailNormalizer#normalize(String)}), and the owner's {@code householdId} or the empty
509	     * string when absent, joined by {@code '|'}. Two owners are duplicates exactly when their whole
510	     * identity keys are equal. The key never contains {@code null} segments, so the create endpoint's
511	     * single duplicate check compares this one value across owners.
512	     *
513	     * @param owner the owner to derive the identity key for
514	     * @return the owner's identity key
515	     */
516	    private String identityKey(Owner owner) {
517	        String telephone = telephoneNormalizer.canonicalize(owner.getTelephone());
518	        String normalizedEmail = emailNormalizer.normalize(owner.getEmail());
519	        String email = normalizedEmail == null ? "" : normalizedEmail;
520	        String household = owner.getHouseholdId() == null ? "" : owner.getHouseholdId();
521	        return telephone + "|" + email + "|" + household;
522	    }
523	
524	    /**
525	     * Reports whether any existing owner already carries the given comparison {@code key}, derived
526	     * from each owner by {@code keyExtractor}. Owners for which the extractor yields {@code null}
527	     * are ignored. The create endpoint's duplicate checks use this to reduce both an existing owner
528	     * and the owner being created to the same canonical key and reject a match.
529	     *
530	     * @param keyExtractor derives an owner's canonical comparison key (may return {@code null})
531	     * @param key the canonical key of the owner being created
532	     * @return {@code true} if some existing owner shares the key
533	     */
534	    private boolean existingOwnerMatches(Function<Owner, String> keyExtractor, String key) {
535	        return this.clinicService.findAllOwners().stream()
536	            .map(keyExtractor)
537	            .filter(Objects::nonNull)
538	            .anyMatch(key::equals);
539	    }
540	
541	    /**
542	     * Delimiter joining the canonical household fields when deriving the shared {@code householdId}.
543	     * A run of whitespace is collapsed to a single space by {@link #canonicalizeHousehold(String)}, so
544	     * this newline can never occur inside a canonical value and the two fields cannot bleed into one
545	     * another across the join.
546	     */
547	    private static final String HOUSEHOLD_KEY_DELIMITER = "\n";
548	
549	    /**
550	     * Reduces a household field ({@code lastName} or {@code address}) to a canonical form for
551	     * case-insensitive, whitespace-insensitive comparison: leading and trailing whitespace is
552	     * trimmed, every run of internal whitespace is collapsed to a single space, and the result is
553	     * lower-cased using {@link java.util.Locale#ROOT} so comparison is locale-independent.
554	     *
555	     * @param value the raw field value, or {@code null}
556	     * @return the canonical value, or {@code null} when {@code value} is {@code null}
557	     */
558	    private String canonicalizeHousehold(String value) {
559	        return value == null ? null : value.trim().replaceAll("\\s+", " ").toLowerCase(java.util.Locale.ROOT);
560	    }
561	
562	    /**
563	     * Derives the stable, shared {@code householdId} for an owner joining a household via
564	     * {@code sharesHousehold}. The identifier is a deterministic function of the canonical
565	     * {@code lastName} and {@code address} (see {@link #canonicalizeHousehold(String)}), so every
566	     * owner with the same last name at the same address - regardless of casing or spacing - is
567	     * assigned the identical value. It is the first 16 upper-case hex characters of the SHA-256 hash
568	     * of the two canonical fields joined by a delimiter that cannot occur in the input.
569	     *
570	     * @param lastName the last name of the owner being created
571	     * @param address the address of the owner being created
572	     * @return the shared household identifier
573	     */
574	    private String householdId(String lastName, String address) {
575	        String key = canonicalizeHousehold(lastName) + HOUSEHOLD_KEY_DELIMITER + canonicalizeHousehold(address);
576	        try {
577	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
578	                .digest(key.getBytes(java.nio.charset.StandardCharsets.UTF_8));
579	            StringBuilder sb = new StringBuilder(digest.length * 2);
580	            for (byte b : digest) {
581	                sb.append(String.format("%02X", b));
582	            }
583	            return sb.substring(0, 16);
584	        } catch (java.security.NoSuchAlgorithmException e) {
585	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
586	        }
587	    }
588	}
